pub(super) fn solve_implicit(
        &self,
        x: &mut Vec<DVec3>,
        predicted: &[DVec3],
        frame: Frame,
        dt: f64,
        contacts: &[PlaneContact],
    ) -> Result<(), TissueError> {
        for _ in 0..self.material.iterations {
            let system = self.linearize(x, predicted, frame, dt, contacts);
            if dot(&system.gradient, &system.gradient) < 1e-16 {
                break;
            }
            let delta = system.direction();
            let slope = dot(&system.gradient, &delta);
            *x = self.descend(x, &delta, slope, |x| {
                self.objective(x, predicted, frame, dt)
                    + contacts
                        .iter()
                        .map(|c| c.energy(x, &self.tets))
                        .sum::<f64>()
            })?;
        }
        Ok(())
    }pub(super) fn energy(&self, positions: &[DVec3], tets: &[Tet]) -> f64fn dot(a: &[DVec3], b: &[DVec3]) -> f64fn direction(&self) -> Vec<DVec3>fn descend( &self, x: &[DVec3], delta: &[DVec3], slope: f64, objective: impl Fn(&[DVec3]) -> f64, ) -> Result<Vec<DVec3>, TissueError>fn linearize( &self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64, contacts: &[PlaneContact], ) -> Systemfn objective(&self, x: &[DVec3], predicted: &[DVec3], frame: Frame, dt: f64) -> f64pub fn energy(&self, positions: &[DVec3], mu: f64, lambda: f64) -> f64
